import {
	Component,
	Element,
	Event,
	EventEmitter,
	Method,
	Prop,
	State,
	Watch,
	h,
} from "@stencil/core";
import FormControl from "../../functional-components/form-control/form-control";
import { generateShortID } from "../../utils/function-helper";
import { hasSlot } from "../../utils/slot";

const id = 0;
const minGap = 0;
const thumbSize = "20px";
type SliderTarget = "start" | "end";

/**
 * @since 0.0.10
 * @status stable
 *
 * @description Sliders allow a user to select a value in a range. Sliders consist of a horizontal bar (a range track) and one or two selection node icons. The range track implies the continuum of values, numeric or relative, that a user can select among.
 *
 * @slot label - The slider's label. Alternatively, you can use the `label` attribute..
 * @slot label-suffix - Non-interactive content to display inline with the slider label.
 * @slot label-info - Interactive informational content, such as a tooltip trigger, displayed next to the slider label.
 * @slot help-text - Help text that describes how to use the slider. Alternatively, you can use the help-text prop.
 *
 * @part base - The component's base wrapper.
 * @part inputstart - The native start slider input.
 * @part inputend - The native end slider input for double slider.
 * @part tooltipstart - The slider tooltip for start position.
 * @part tooltipend - The slider tooltip for end position.
 * @part track - The slider's track.
 */
@Component({
	tag: "hbr-slider",
	styleUrl: "slider.scss",
	shadow: true,
	formAssociated: true,
})
export class HbrSlider {
	inputstart: HTMLInputElement;
	inputend: HTMLInputElement;
	labelId = `slider-label-${id}`;
	input: HTMLInputElement;

	@Element() host: HTMLHbrSliderElement;

	sliderTrack;
	sliderMaxValue;
	tickMarks;
	outputStart: HTMLElement;
	outputEnd: HTMLElement;
	resizeObserver: ResizeObserver;

	@State() activeFocusTarget: SliderTarget | null = null;
	@State() activeHoverTarget: SliderTarget | null = null;
	@State() hasContent = false;

	@State() arrayXTransform: Array<number | undefined> = [];
	@State() uuid: string = generateShortID();
	@State() hasLabelSlot = false;
	@State() hasLabelInfoSlot = false;
	@State() hasHelpTextSlot = false;
	@State() hasHelpText = false;
	@State() hasFrontSlot = false;
	@State() hasRearSlot = false;

	/** The name of the slider, submitted as a name/value pair with form data. */
	@Prop() name = "";

	/** The current value of the slider, submitted as a name/value pair with form data.
	 * Use event.target.value to retrieve values on change event.
	 * */
	@Prop({ mutable: true }) value: number | Array<number>;

	/** Disables the slider. */
	@Prop({ reflect: true }) disabled = false;

	/** Prevents users from adjusting the slider while preserving value tooltips. */
	@Prop({ reflect: true }) readonly = false;

	/** Makes the slider a required field. */
	@Prop({ reflect: true }) required = false;

	/** Use  double range slider */
	@Prop({ reflect: true }) double = false;

	/** The minimum acceptable value of the slider. */
	@Prop() min = 0;

	/** The maximum acceptable value of the slider. */
	@Prop() max = 100;

	/** Start pointer of slider. It defaults to min */
	@Prop({ reflect: true, mutable: true }) start = this.min;

	/** End pointer of slider. It defaults to max */
	@Prop({ reflect: true, mutable: true }) end = this.max;

	/** The interval at which the slider will increase and decrease. */
	@Prop() step = 1;

	/** Graduated increments allow users to select from specified incremental values. */
	@Prop() discrete = false;

	/** The preferred placement of the slider's tooltip. */
	@Prop() tooltip: "top" | "bottom" | "none" = "top";

	/** Value mark labels allow users to see minimum values, maximum values, and step values in between to guide user input. */
	@Prop() values = [this.min, this.max];

	/** Attributes related to screen readers. */
	@Prop() aria: { label: string; labelStart: string; labelEnd: string };

	/** Slider with uneven steps. */
	@Prop() uneven: boolean;

	/**
	 * A function used to format the tooltip's value. The slider's value is passed as the first and only argument. The
	 * function should return a string to display in the tooltip.
	 */
	@Prop() tooltipFormatter = (value: number) =>
		typeof value === "number" ? value.toString() : value;

	/** The slider's label. If you need to display HTML, use the `label` slot instead. */
	@Prop({ reflect: true }) label = "";

	/** The slider's help text. If you need to display HTML, use the help-text slot instead. */
	@Prop({ reflect: true }) helpText = "";

	/** The slider's help text id. */
	@Prop({ reflect: true }) helpTextId = `slider-help-text-${id}`;

	@State() valueStart: number;
	@State() valueEnd: number;

	/** Emitted when the control's value changes and mouse is released. */
	@Event({ eventName: "hbr-change" }) hbrChange: EventEmitter;

	/** Emitted when the control's value changes. */
	@Event({ eventName: "hbr-input" }) hbrInput: EventEmitter;

	/** Emitted when the control loses focus. */
	@Event({ eventName: "hbr-blur" }) hbrBlur: EventEmitter;

	/** Emitted when the control gains focus. */
	@Event({ eventName: "hbr-focus" }) hbrFocus: EventEmitter;

	connectedCallback() {
		this._onInputStart = this._onInputStart.bind(this);
		this._onInputEnd = this._onInputEnd.bind(this);
		this._onChange = this._onChange.bind(this);
		this.handleTouchStart = this.handleTouchStart.bind(this);
		this.handleBlur = this.handleBlur.bind(this);
		this.handleFocus = this.handleFocus.bind(this);
		this.handleMouseEnter = this.handleMouseEnter.bind(this);
		this.handleMouseLeave = this.handleMouseLeave.bind(this);
		this.handleMouseDown = this.handleMouseDown.bind(this);
		this.handleMouseUp = this.handleMouseUp.bind(this);
		this.handleTickMarkClick = this.handleTickMarkClick.bind(this);
		this.host.shadowRoot.addEventListener("slotchange", this.handleSlotChange);
	}

	componentWillLoad() {
		this.discretePoints();
		this.handleSlotChange();
		if (this.value) {
			if (this.double) {
				if (!Array.isArray(this.value)) {
					return;
				}
				this.start = this.value[0] as number;
				this.end = this.value[1] as number;
			} else {
				this.start = this.value as number;
			}
		}

		/** https://github.com/cisco-harbor/elements/issues/596 */
		if (this.valueStart === undefined) {
			this.valueStart = this.start || 0;
		}
		if (this.valueEnd === undefined) {
			this.valueEnd = this.end || 0;
		}
	}

	disconnectedCallback() {
		if (this.resizeObserver) {
			this.resizeObserver.unobserve(this.inputstart);
			if (this.double) this.resizeObserver.unobserve(this.inputend);
			this.resizeObserver.unobserve(this[`sliderTrack${this.uuid}`]);
		}

		//Commenting for now. It might be added later.
		//this.resizeObserver.unobserve(this[`pipLabel$1${this.uuid}`]);
		this.host.shadowRoot.removeEventListener(
			"slotchange",
			this.handleSlotChange,
		);
	}

	@Watch("label")
	handleLabelChange() {
		this.handleSlotChange();
	}

	@Watch("min")
	handleMinChange() {
		this.values[0] = this.min;
	}

	@Watch("max")
	handleMaxChange() {
		this.values[1] = this.max;
	}

	@Watch("start")
	handleStartChange() {
		this.valueStart = this.start < this.min ? this.min : this.start;
	}

	@Watch("end")
	handleEndChange() {
		this.valueEnd = this.end > this.max ? this.max : this.end;
	}

	@Watch("value")
	handleValueChange() {
		if (this.value) {
			if (this.double) {
				if (!Array.isArray(this.value)) {
					return;
				}
				this.start = this.value[0] as number;
				this.end = this.value[1] as number;
			} else {
				this.start = this.value as number;
			}
		}
	}

	@Watch("disabled")
	handleDisabledChange() {
		if (this.disabled) {
			this.activeFocusTarget = null;
			this.activeHoverTarget = null;
		}
	}

	componentDidLoad() {
		this.resizeObserver = new ResizeObserver((entries) =>
			this.onResizeCallback(entries),
		);
		setTimeout(() => {
			this.resizeObserver.observe(this[`sliderTrack${this.uuid}`]);
		});
	}

	componentDidRender() {
		this.sliderMaxValue = this.inputstart.max;
		this.fillColor();

		setTimeout(() => {
			this.syncLabels();
			this.syncTickStyle();
			this.syncTooltipStart();
			if (this.double) this.syncTooltipEnd();
		});
	}

	onResizeCallback(entries) {
		for (const entry of entries) {
			if (entry.target.className === "range--slider-track") {
				this.syncLabels();
			} else if (entry.target.id === "slider-1") {
				this.syncTooltipStart();
			} else if (entry.target.id === "slider-2") {
				this.syncTooltipEnd();
			}
		}
	}

	/** Sets focus on the input. */
	@Method()
	async setFocus(options?: FocusOptions) {
		if (this.disabled) {
			return;
		}
		this.inputstart.focus(options);
	}

	/** Removes focus from the input. */
	@Method()
	async removeFocus() {
		this.inputstart.blur();
	}

	/** Checks for validity and shows the browser's validation message if the control is invalid. */
	@Method()
	async reportValidity() {
		return this.input.reportValidity();
	}

	handleTouchStart(event: TouchEvent) {
		if (this.readonly) {
			event.preventDefault();
			return;
		}
		this.setFocus();
	}

	syncTooltipStart() {
		this.calculateX(
			this.valueStart,
			this.inputstart,
			`outputStart${this.uuid}`,
		);
	}

	syncLabels() {
		this.values.forEach((ele, index) => {
			//Do some binary search here.
			//The plan of using arrayXTransform was to add more pipes in the future.
			//Since parseFloat, sometimes this.max does not match last value using value = value + step.
			//Find a more reliable way to match arrayXTransform values with interval.
			//this.arrayXTransform.forEach((ele2)=> {
			//if (ele2 === ele) {
			const percent = Math.max(0, (ele - this.min) / (this.max - this.min));
			const inputWidth = this.inputstart.offsetWidth;
			const x = `calc(${
				inputWidth * percent
			}px - calc(calc(${percent} * ${thumbSize}) - calc(${thumbSize} / 2)))`;
			this[`pipLabel${index}${this.uuid}`].style.transform = `translateX(${x})`;
			// }
			//})
		});
	}

	syncTooltipEnd() {
		this.calculateX(this.valueEnd, this.inputend, `outputEnd${this.uuid}`);
	}
	calculateX(value, slider, output) {
		if (
			this.tooltip !== "none" &&
			value !== undefined &&
			value !== null &&
			slider &&
			output
		) {
			const percent = Math.max(0, (value - this.min) / (this.max - this.min));
			const inputWidth = slider.offsetWidth;
			const tooltipWidth = this[output].offsetWidth;
			//const thumbSize = getComputedStyle(this.inputstart).getPropertyValue("--thumb-size");
			const x = `calc(${
				inputWidth * percent
			}px - calc(calc(${percent} * ${thumbSize}) - calc(${thumbSize} / 2)))`;
			this[output].style.transform = `translateX(${x})`;
			this[output].style.marginLeft = `-${tooltipWidth / 2}px`;
			//componentDidRender can't capture some elements yet like Tooltip.
			//Commenting for now.
			//this.hasTooltip = true;
		}
	}

	_onInputStart() {
		if (this.readonly) {
			this.inputstart.value = this.valueStart.toString();
			return;
		}
		this.fillColor();
		this.valueStart = parseFloat(this.inputstart.value);
		if (!this.double) {
			this.value = parseFloat(this.inputstart.value);
		} else {
			this.value =
				parseFloat(this.inputend.value) - parseFloat(this.inputstart.value) <=
				minGap
					? [parseFloat(this.inputend.value), parseFloat(this.inputstart.value)]
					: [
							parseFloat(this.inputstart.value),
							parseFloat(this.inputend.value),
					  ];
		}
		requestAnimationFrame(() => {
			this.syncTooltipStart();
			this.syncTickStyle();
		});
		this.hbrInput.emit();
	}

	_onChange(event: Event) {
		if (this.readonly) {
			return;
		}
		const target = event.target === this.inputstart ? "start" : "end";
		this.hbrChange.emit({ target });
	}

	_onInputEnd() {
		if (this.readonly) {
			this.inputend.value = this.valueEnd.toString();
			return;
		}
		this.fillColor();
		this.valueEnd = parseFloat(this.inputend.value);
		if (!this.double) {
			this.value = parseFloat(this.inputend.value);
		} else {
			this.value =
				parseFloat(this.inputend.value) - parseFloat(this.inputstart.value) <=
				minGap
					? [parseFloat(this.inputend.value), parseFloat(this.inputstart.value)]
					: [
							parseFloat(this.inputstart.value),
							parseFloat(this.inputend.value),
					  ];
		}
		requestAnimationFrame(() => {
			this.syncTooltipEnd();
			this.syncTickStyle();
		});
		this.hbrInput.emit();
	}
	syncTickStyle() {
		Array.from(this[`tickMarks${this.uuid}`].children).forEach(
			(ele: HTMLElement) => {
				const hidden = ele.classList.contains("range__hidden-tick");
				if (!this.double) {
					if (
						parseFloat(this.inputstart.value) > parseFloat(ele.dataset.value)
					) {
						ele.className = `range__tick-mark${
							this.double ? "--double" : ""
						} range__tick-mark--inactive`;
					} else {
						ele.className = `range__tick-mark${
							this.double ? "--double" : ""
						} range__tick-mark--active`;
					}
				} else {
					if (
						parseFloat(this.inputstart.value) > parseFloat(ele.dataset.value) ||
						parseFloat(this.inputend.value) < parseFloat(ele.dataset.value)
					) {
						ele.className = `range__tick-mark${
							this.double ? "--double" : ""
						} range__tick-mark--active`;
					} else {
						ele.className = `range__tick-mark${
							this.double ? "--double" : ""
						} range__tick-mark--inactive`;
					}
				}
				if (hidden) {
					ele.classList.add("range__hidden-tick");
				}
			},
		);
	}

	fillColor() {
		const totalRange = this.max - this.min;
		const unselectedColor = this.disabled
			? "var(--slider-range-unselected-color-disabled)"
			: "var(--slider-range-unselected-color)";
		const selectedColor = this.disabled
			? "var(--slider-range-selected-color-disabled)"
			: "var(--slider-range-selected-color)";

		if (this.double) {
			const nonShadowSectionLeft = parseFloat(this.inputstart.value) - this.min;
			const nonShadowSectionRight = parseFloat(this.inputend.value) - this.min;
			const percent1 = (nonShadowSectionLeft / totalRange) * 100;
			const percent2 = (nonShadowSectionRight / totalRange) * 100;
			this[`sliderTrack${this.uuid}`].style.background = `linear-gradient(to right, 
          ${unselectedColor} ${percent1}%, 
          ${selectedColor} ${percent1}% , 
          ${selectedColor} ${percent2}%, 
          ${unselectedColor} ${percent2}%)`;
		} else {
			const shadowSection = parseFloat(this.inputstart.value) - this.min;
			const percent1 = (shadowSection / totalRange) * 100;
			const percent2 = 100;
			this[`sliderTrack${this.uuid}`].style.background = `linear-gradient(to right, 
          ${selectedColor} ${percent1}% , 
          ${unselectedColor} ${percent1}%,
           ${unselectedColor} ${percent2}%)`;
		}
	}

	discretePoints() {
		let temp = [];
		if (this.discrete && this.uneven) {
			temp = [...this.values.filter((ele) => !Number.isInteger(ele))];
		}
		const range = this.max - this.min;
		const numberOfPoints = range / this.step;
		const arrayTemp = [];
		let initialValue = this.min;
		Array.from({ length: numberOfPoints + 1 })
			.fill("1")
			.forEach(() => {
				arrayTemp.push(initialValue);
				if (temp.length > 0) {
					/** Ensure that floating-point numbers are added to the arrayTemp so that its tick can be updated. */
					if (Math.floor(temp[0]) === initialValue) {
						arrayTemp.push(temp[0]);
						temp.shift();
					}
				}
				initialValue = initialValue + this.step;
			});
		this.arrayXTransform = arrayTemp;
	}

	handleBlur(target: SliderTarget) {
		if (this.activeFocusTarget === target) {
			this.activeFocusTarget = null;
		}
		this.hbrBlur.emit();
		this.resizeObserver.unobserve(this.inputstart);
		if (this.double) this.resizeObserver.unobserve(this.inputend);
	}

	handleFocus(target: SliderTarget) {
		if (this.disabled) {
			return;
		}
		this.activeFocusTarget = target;
		this.hbrFocus.emit();
		this.resizeObserver.observe(this.inputstart);
		if (this.double) this.resizeObserver.observe(this.inputend);
	}

	handleMouseEnter(target: SliderTarget) {
		if (this.disabled) {
			return;
		}
		this.activeHoverTarget = target;
	}
	handleMouseLeave(target: SliderTarget) {
		if (this.activeHoverTarget === target) {
			this.activeHoverTarget = null;
		}
	}
	handleMouseDown(target: SliderTarget, event: MouseEvent) {
		if (this.disabled) {
			return;
		}
		if (this.readonly) {
			event.preventDefault();
			return;
		}
		this.activeFocusTarget = target;
	}
	handleMouseUp(target: SliderTarget) {
		if (this.disabled || this.readonly) {
			return;
		}
		this.activeFocusTarget = target;
		this.activeHoverTarget = target;
	}

	handleTickMarkClick(event: MouseEvent) {
		if (this.disabled || this.readonly) {
			return;
		}
		if (this.double) {
			const target = event.target as HTMLElement;
			if (target) {
				const { value } = target.dataset;
				const { start, end } = this;
				const diffToStart = Math.abs(parseFloat(value) - start);
				const diffToEnd = Math.abs(parseFloat(value) - end);

				/** depends on the distance between clicked and start/end, dynamically update either start or end value.Depending on the distance between the clicked position and the start or end, dynamically update either the start or end value. */
				if (diffToStart <= diffToEnd) {
					this.start = parseFloat(value);
					this.value = [this.start, parseFloat(this.inputend.value)];
					this.inputstart.focus();
				} else {
					this.end = parseFloat(value);
					this.value = [parseFloat(this.inputstart.value), this.end];
					this.inputend.focus();
				}
			}
		} else {
			/** only triggers in non-double mode */
			this.start = parseFloat((event.target as HTMLElement).dataset.value);
			this.value = this.start;
			this.inputstart.focus();
			setTimeout(() => {
				this.hbrChange.emit();
			});
		}
	}

	handleKeyDown(event: KeyboardEvent) {
		const valueChangeKeys = [
			"ArrowDown",
			"ArrowLeft",
			"ArrowRight",
			"ArrowUp",
			"End",
			"Home",
			"PageDown",
			"PageUp",
		];
		if (this.readonly && valueChangeKeys.includes(event.key)) {
			event.preventDefault();
		}
	}

	handleSlotChange() {
		this.hasLabelSlot = hasSlot(this.host, "label");
		this.hasLabelInfoSlot = hasSlot(this.host, "label-info");
		this.hasContent = hasSlot(this.host);
		this.hasFrontSlot = hasSlot(this.host, "front");
		this.hasRearSlot = hasSlot(this.host, "rear");
		this.hasHelpTextSlot = hasSlot(this.host, "help-text");
		this.hasHelpText = this.helpText ? true : !!this.hasHelpTextSlot;
	}

	render() {
		const activeTooltipTarget = this.disabled
			? null
			: this.activeHoverTarget || this.activeFocusTarget;

		return (
			<FormControl
				inputId=""
				labelId={this.labelId}
				size="medium"
				isRequired={this.required}
				hasLabelSlot={this.hasLabelSlot}
				hasLabelInfoSlot={this.hasLabelInfoSlot}
				hasFrontSlot={this.hasFrontSlot}
				hasRearSlot={this.hasRearSlot}
				label={this.label}
				helpText={this.helpText}
				hasHelpTextSlot={this.hasHelpText}
				helpTextId={this.helpTextId}
				isDisabled={this.disabled}
			>
				<div class="wrapper">
					<div
						part="base"
						class={{
							range: true,
							// States
							"range--disabled": this.disabled,
							"range--readonly": this.readonly,
							"range--double": this.double,
							"range--focused-start": this.activeFocusTarget === "start",
							"range--focused-end": this.activeFocusTarget === "end",
							"range--tooltip-top": this.tooltip === "top",
							"range--tooltip-bottom": this.tooltip === "bottom",
						}}
						onTouchStart={this.handleTouchStart}
					>
						<div
							part="track"
							class="range--slider-track"
							ref={(el) => {
								this[`sliderTrack${this.uuid}`] = el;
							}}
						/>
						<div
							class="range__tick-marks"
							part="ticks"
							ref={(el) => {
								this[`tickMarks${this.uuid}`] = el;
							}}
						>
							{this.arrayXTransform.map((ele) => {
								if (this.discrete) {
									if (this.uneven) {
										if (this.values.includes(ele)) {
											return (
												<div
													class={`range__tick-mark${
														this.double ? "--double" : ""
													} range__tick-mark--inactive`}
													data-value={ele}
													onClick={
														!this.double ? this.handleTickMarkClick : undefined
													}
												/>
											);
										}
									} else {
										return (
											<div
												class={`range__tick-mark${
													this.double ? "--double" : ""
												} range__tick-mark--inactive`}
												data-value={ele}
												onClick={
													!this.double ? this.handleTickMarkClick : undefined
												}
											/>
										);
									}
								}
								return (
									<span
										class={`range__hidden-tick range__tick-mark${
											this.double ? "--double" : ""
										} range__tick-mark--inactive`}
										data-value={ele}
										onClick={this.handleTickMarkClick}
									/>
								);
							})}
						</div>
						<div class="range__pip-label-container" part="pips">
							{this.values.map((ele, index) => {
								return (
									<div
										class="range__pip-label"
										ref={(el) => {
											this[`pipLabel${index}${this.uuid}`] = el;
										}}
									>
										{ele}
									</div>
								);
							})}
						</div>
						<input
							part="inputstart"
							ref={(el) => {
								this.inputstart = el;
							}}
							class="range__input range__input--start"
							name={this.name}
							type="range"
							tabIndex={0}
							min={this.min}
							max={this.max}
							step={this.step}
							value={
								!this.double && this.value && typeof this.value === "number"
									? this.value
									: this.valueStart
							}
							disabled={this.disabled}
							id="slider-1"
							onInput={this._onInputStart}
							onChange={this._onChange}
							onFocus={() => this.handleFocus("start")}
							onBlur={() => this.handleBlur("start")}
							onMouseEnter={() => this.handleMouseEnter("start")}
							onMouseLeave={() => this.handleMouseLeave("start")}
							onMouseDown={(event) => this.handleMouseDown("start", event)}
							onMouseUp={() => this.handleMouseUp("start")}
							onTouchEnd={() => this.handleMouseUp("start")}
							onKeyDown={(event) => this.handleKeyDown(event)}
							aria-label={
								(!this.label && this.aria?.label) || this.aria?.labelStart
							}
							aria-labelledby={this.labelId}
							aria-readonly={this.readonly ? "true" : undefined}
						/>
						{this.tooltip !== "none" && (
							<div
								part="tooltipstart"
								ref={(el) => {
									this[`outputStart${this.uuid}`] = el;
								}}
								class={{
									range__tooltip: true,
									"range__tooltip--visible": activeTooltipTarget === "start",
								}}
							>
								{this.tooltipFormatter(this.valueStart)}
							</div>
						)}
						{this.double && (
							<input
								part="inputend"
								ref={(el) => {
									this.inputend = el;
								}}
								class="range__input range__input--end"
								name={this.name}
								type="range"
								tabIndex={0}
								min={this.min}
								max={this.max}
								step={this.step}
								value={this.valueEnd}
								disabled={this.disabled}
								id="slider-2"
								onInput={this._onInputEnd}
								onChange={this._onChange}
								onFocus={() => this.handleFocus("end")}
								onBlur={() => this.handleBlur("end")}
								onMouseEnter={() => this.handleMouseEnter("end")}
								onMouseLeave={() => this.handleMouseLeave("end")}
								onMouseDown={(event) => this.handleMouseDown("end", event)}
								onMouseUp={() => this.handleMouseUp("end")}
								onTouchEnd={() => this.handleMouseUp("end")}
								onKeyDown={(event) => this.handleKeyDown(event)}
								aria-label={!this.label && this.aria?.labelEnd}
								aria-labelledby={this.labelId}
								aria-readonly={this.readonly ? "true" : undefined}
							/>
						)}
						{this.tooltip !== "none" && this.double && (
							<div
								part="tooltipend"
								ref={(el) => {
									this[`outputEnd${this.uuid}`] = el;
								}}
								class={{
									range__tooltip: true,
									"range__tooltip--visible": activeTooltipTarget === "end",
								}}
							>
								{this.tooltipFormatter(this.valueEnd)}
							</div>
						)}
					</div>
				</div>
			</FormControl>
		);
	}
}
